const fs = require('fs');
const readline = require('readline');
const path = require('path');

const brainDir = 'C:/Users/admin/.gemini/antigravity-ide/brain';
const conversations = [
  'fe5f3da4-28e8-4953-b097-ce64bd94b483',
  '53b57104-e4e2-40d0-adc5-813cc565893f'
];

async function extractOriginals() {
  for (const conv of conversations) {
    const transcriptPath = path.join(brainDir, conv, '.system_generated', 'logs', 'transcript_full.jsonl');
    if (!fs.existsSync(transcriptPath)) continue;

    console.log(`Searching transcript of ${conv} for file reads...`);
    const fileStream = fs.createReadStream(transcriptPath);
    const rl = readline.createInterface({
      input: fileStream,
      crlfDelay: Infinity
    });

    for await (const line of rl) {
      if (!line.trim()) continue;
      const step = JSON.parse(line);

      // We look for SYSTEM steps where the model called view_file in the previous step
      if (step.source === 'SYSTEM' && step.content) {
        // Find if this is a response to view_file
        // Let's print some info
        const contentStr = String(step.content);
        if (contentStr.includes('File Path: `file:///c:/Users/admin/Desktop/billing_inventory/backend/src/routes/purchase.js`')) {
          console.log(`Found a view_file output for purchase.js in conversation ${conv}, step ${step.step_index}`);
          // Let's write this output to a temporary file
          const outPath = path.join(brainDir, '53b57104-e4e2-40d0-adc5-813cc565893f', 'scratch', `view_purchase_js_${conv}_step_${step.step_index}.txt`);
          fs.writeFileSync(outPath, contentStr);
          console.log(`Saved to ${outPath}`);
        }
        if (contentStr.includes('File Path: `file:///c:/Users/admin/Desktop/billing_inventory/backend/src/routes/csa.js`')) {
          console.log(`Found a view_file output for csa.js in conversation ${conv}, step ${step.step_index}`);
          const outPath = path.join(brainDir, '53b57104-e4e2-40d0-adc5-813cc565893f', 'scratch', `view_csa_js_${conv}_step_${step.step_index}.txt`);
          fs.writeFileSync(outPath, contentStr);
          console.log(`Saved to ${outPath}`);
        }
      }
    }
  }
}

extractOriginals().catch(err => {
  console.error(err);
});
